// 2026 马年标准生肖顺序 (Index 0 = 1号的生肖)
// 顺序: 马->蛇->龙->兔->虎->牛->鼠->猪->狗->鸡->猴->羊
const ZODIAC_SEQ = ['马', '蛇', '龙', '兔', '虎', '牛', '鼠', '猪', '狗', '鸡', '猴', '羊'];
const TARGET_YEAR = 2026; // 当前 NUMBER_MAP 配置对应的年份

